## 26.2 Citation component

`components/citation-panel.ts`:

```typescript
import type {
    Locator
} from "@playwright/test";

export class CitationPanel {

    readonly links: Locator;

    constructor(
        private readonly root: Locator
    ) {

        this.links = root.getByRole("link");
    }

    link(title: string): Locator {

        return this.root.getByRole(

            "link",

            {
                name: title,
                exact: true
            }
        );
    }
}
```

## 26.3 ChatPage object

`pages/chat.page.ts`:

```typescript
import type {
    Page,
    Locator
} from "@playwright/test";

import { CitationPanel }
    from "../components/citation-panel";

export class ChatPage {

    private readonly question: Locator;

    readonly send: Locator;

    readonly answer: Locator;

    readonly status: Locator;

    readonly citations: CitationPanel;

    constructor(
        private readonly page: Page
    ) {

        this.question =
            page.getByLabel("Question");

        this.send = page.getByRole(

            "button",

            { name: "Send" }
        );

        this.answer =
            page.getByTestId("answer");

        this.status =
            page.getByTestId("generation-status");

        this.citations = new CitationPanel(

            page.getByRole("region", {

                name: "Citations"
            })
        );
    }

    async open(): Promise<void> {

        await this.page.goto("/");
    }

    async ask(question: string): Promise<void> {

        await this.question.fill(question);

        await this.send.click();
    }
}
```

## 26.4 Fixture dependency injection

`fixtures/test.ts`:

```typescript
import {
    test as base,
    expect
} from "@playwright/test";

import { ChatPage } from "../pages/chat.page";

type Fixtures = {

    chatPage: ChatPage;
};

export const test = base.extend<Fixtures>({

    chatPage: async ({ page }, use) => {

        await use(new ChatPage(page));
    }
});

export { expect };
```

The page object depends on the built-in page fixture. The browser and context remain managed by Playwright Test.

## 26.5 Test data factory

`factories/chat.factory.ts`:

```typescript
export type ChatInput = {

    question: string;
};

export function buildQuestion(

    overrides: Partial<ChatInput> = {}

): ChatInput {

    return {

        question: "What is RAG?",

        ...overrides
    };
}
```

## 26.6 Runtime response schema

`schemas/chat.schema.ts`:

```typescript
import { z } from "zod";

export const CitationSchema = z.object({

    title: z.string(),

    url: z.string()
});

export const ChatResponseSchema = z.object({

    answer: z.string(),

    citations: z.array(CitationSchema)
});

export type ChatResponse =
    z.infer<typeof ChatResponseSchema>;
```

This creates one runtime contract and a corresponding TypeScript type.

## 26.7 Parameterized browser tests

`tests/chat.spec.ts`:

```typescript
import {
    test,
    expect
} from "../fixtures/test";

const cases = [

    {
        id: "rag",

        question: "What is RAG?",

        answer:
            "RAG combines retrieval and generation.",

        citation: "RAG Guide",

        href: "/documents/rag"
    },

    {
        id: "langgraph",

        question: "What is LangGraph?",

        answer:
            "LangGraph models workflows as graphs.",

        citation: "LangGraph Guide",

        href: "/documents/langgraph"
    },

    {
        id: "fastapi",

        question: "What is FastAPI?",

        answer:
            "FastAPI supports Python API development.",

        citation: "FastAPI Guide",

        href: "/documents/fastapi"
    }
] as const;

for (const item of cases) {

    test(

        `Chat response: ${item.id}`,

        {
            tag: ["@smoke", "@rag"]
        },

        async ({ chatPage }) => {

            await test.step(
                "Open chatbot and submit question",

                async () => {

                    await chatPage.open();

                    await chatPage.ask(
                        item.question
                    );
                }
            );

            await test.step(
                "Verify complete answer",

                async () => {

                    await expect(

                        chatPage.status

                    ).toHaveText("Completed");

                    await expect(

                        chatPage.answer

                    ).toHaveText(item.answer);
                }
            );

            await test.step(
                "Verify citation and UI recovery",

                async () => {

                    await expect(

                        chatPage.citations.links

                    ).toHaveCount(1);

                    await expect(

                        chatPage.citations.link(
                            item.citation
                        )

                    ).toHaveAttribute(
                        "href",
                        item.href
                    );

                    await expect(

                        chatPage.send

                    ).toBeEnabled();
                }
            );
        }
    );
}
```

Notice how the test reads as a business scenario rather than a collection of selectors.

## 26.8 Backend API tests

`tests/chat-api.spec.ts`:

```typescript
import {
    test,
    expect
} from "@playwright/test";

import { buildQuestion }
    from "../factories/chat.factory";

import { ChatResponseSchema }
    from "../schemas/chat.schema";

test("Verify chat API contract", async ({ request }) => {

    const response = await request.post(

        "/api/chat",

        {
            data: buildQuestion()
        }
    );

    expect(response.status()).toBe(200);

    const result = ChatResponseSchema.parse(

        await response.json()
    );

    expect(result.answer).toBe(

        "RAG combines retrieval and generation."
    );

    expect(result.citations).toEqual([

        {
            title: "RAG Guide",

            url: "/documents/rag"
        }
    ]);
});

test("Reject empty question", async ({ request }) => {

    const response = await request.post(

        "/api/chat",

        {
            data: buildQuestion({
                question: ""
            })
        }
    );

    expect(response.status()).toBe(422);
});
```

## 26.9 Production-oriented Playwright configuration

`playwright.config.ts`:

```typescript
import {
    defineConfig,
    devices
} from "@playwright/test";

const baseURL = "http://127.0.0.1:8000";

export default defineConfig({

    testDir: "./tests",

    fullyParallel: true,

    forbidOnly: !!process.env.CI,

    workers: 2,

    retries: process.env.CI ? 1 : 0,

    timeout: 30000,

    expect: {

        timeout: 5000
    },

    reporter: [

        ["list"],

        ["html", {
            open: "never"
        }]
    ],

    use: {

        baseURL,

        actionTimeout: 10000,

        navigationTimeout: 15000,

        screenshot: "only-on-failure",

        trace: "retain-on-failure",

        video: "retain-on-failure"
    },

    projects: [

        {
            name: "chromium",

            use: {
                ...devices["Desktop Chrome"]
            }
        }
    ],

    webServer: {

        command:
            "python -m uvicorn app:app --port 8000",

        url: `${baseURL}/health`,

        reuseExistingServer: !process.env.CI,

        timeout: 30000
    }
});
```

The Python command must use an environment with FastAPI and Uvicorn installed, and `app.py` must be available in the working directory.

## 26.10 TypeScript compiler configuration

`tsconfig.json`:

```json
{
    "compilerOptions": {
        "target": "ES2022",
        "module": "ESNext",
        "moduleResolution": "Bundler",
        "strict": true,
        "noEmit": true,
        "esModuleInterop": true,
        "skipLibCheck": true
    },
    "include": [
        "**/*.ts"
    ],
    "exclude": [
        "node_modules",
        "test-results"
    ]
}
```

This lab uses the Playwright Test runner's TypeScript transformation rather than emitting Node.js files directly.

For standalone compiled Node.js ESM applications, use an appropriate NodeNext configuration and import conventions, as discussed in our earlier TypeScript modules.

## 26.11 Run the framework

```bash
npx tsc --noEmit
```

```bash
npx playwright test
```

Run smoke tests:

```bash
npx playwright test --grep "@smoke"
```

Run a particular browser test:

```bash
npx playwright test tests/chat.spec.ts
```

Run the API suite:

```bash
npx playwright test tests/chat-api.spec.ts
```

Inspect the HTML report:

```bash
npx playwright show-report
```

